175	async function handleUserMessage(
176	  ws: WebSocket,
177	  session: ChatSession,
178	  orchestrator: ChatOrchestrator,
179	  content: string,
180	  signal: AbortSignal | undefined
181	): Promise<void> {
182	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
183	
184	  const userEntry = createUserEntry(content);
185	  const userIndex = appendEntry(session, userEntry);
186	  sendUpsert(ws, userIndex, userEntry);
187	
188	  const parser = new ThinkingTagParser();
189	  const state: StreamState = {
190	    thinkingIndex: null,
191	    assistantIndex: null,
192	    suppressOutput: false,
193	    sentAssistantIndices: [],
194	  };
195	
196	  let textChunkCount = 0;
197	
198	  try {
199	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
200	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
201	      if (signal?.aborted) break;
202	      textChunkCount = logChunk(chunk, textChunkCount);
203	      processChunk(ws, session, state, parser, chunk);
204	    }
205	  } finally {
206	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
207	    flushHeldText(ws, session, state, parser);
208	    closeCutOff(ws, session, state, 'thinkingIndex');
209	    closeCutOff(ws, session, state, 'assistantIndex');
210	  }
211	
212	  if (textChunkCount > 0) {
213	    log.debug('stream', `received ${textChunkCount} text chunks`);
214	  }
215	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
216	}
