218	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
219	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
220	  if (chunk.type === 'text') return textChunkCount + 1;
221	
222	  if (textChunkCount > 0) {
223	    log.debug('stream', `received ${textChunkCount} text chunks`);
224	  }
225	
226	  if (chunk.type === 'tool_result') {
227	    log.debug('stream', 'tool_result chunk', {
228	      messageCount: chunk.clientMessages.length,
229	      types: chunk.clientMessages.map(m => m.type),
230	    });
231	    return 0;
232	  }
233	
234	  log.debug('stream', 'chunk', {type: chunk.type});
235	  return 0;
236	}
