44	const harness = (chunks: MessageChunk[], {failWith, pauseAfter, sessionStore}: StreamScript = {}) => {
45	  const sent: OutgoingMessage[] = [];
46	  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
47	
48	  const stream = async function* (): AsyncGenerator<MessageChunk> {
49	    for (const [position, chunk] of chunks.entries()) {
50	      if (pauseAfter && position === pauseAfter.chunks) await pauseAfter.until;
51	      yield chunk;
52	    }
53	    if (failWith) throw failWith;
54	  };
55	
56	  const processMessageStream = jest.fn(stream);
57	  const orchestrator = {processMessageStream} as unknown as ChatOrchestrator;
58	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
59	
60	  const handle = createMessageHandler(orchestrator, sessionStore);
61	
62	  return {
63	    session,
64	    processMessageStream,
65	    sent,
66	    frames: () => wire(sent),
67	    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
68	      handle(ws, session, raw, signal),
69	  };
70	};
