export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/...).
  const lock = new PerSessionLock();
  // One answer chain per socket: immediate frames are answered in arrival order, so a frame sent later cannot overtake one sent earlier.
  const answered = new WeakMap<WebSocket, Promise<void>>();
