export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
  const lock = new PerSessionLock();
  // One answer chain per socket: a frame answered beside the turn still owes its socket the arrival order.
  const answered = new WeakMap<WebSocket, Promise<void>>();
  return function handleMessage(
    ws: WebSocket,
    session: ChatSession,
    rawMessage: unknown,
    signal?: AbortSignal
  ): Promise<void> {
    const validation = validateMessage(rawMessage);
    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
    if (isUserMessageFrame(rawMessage)) {
      return lock.run(session.sessionId, () =>
        answerInTurn(ws, session, orchestrator, validation, signal, sessionStore)
      );
    }
    return answerBesideTheTurn(ws, session, validation, sessionStore, answered);
  };
}

// Answered once the answers this socket is already owed have gone out: a frame sent after a list
// must not see its pong overtake that list. It never waits on the lock, so it still answers mid-turn.
function answerBesideTheTurn(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined,
  answered: WeakMap<WebSocket, Promise<void>>
): Promise<void> {
  const owed = answered.get(ws) ?? Promise.resolve();
  const answer = owed.then(() => wsErrorHandler(ws, () => answerFrame(ws, session, validation, sessionStore)));
  // The tail never rejects: the next frame chains on it, and the connection dispatches without awaiting.
  answered.set(ws, answer.catch(() => undefined));
  return answer;
}

